def _eval_multiple_select_target_elements(self, eval_result, segment):
    if eval_result.first_new_line_idx == -1:
        # there are multiple select targets but no new lines
        # Create fixes to add newlines and proper indentation
        fixes = []

        # Find segments in order
        segments_info = []
        for i, seg in enumerate(segment.segments):
            if seg.is_type("keyword") and seg.name == "SELECT":
                segments_info.append(("select", i, seg))
            elif seg.is_type("select_target_element"):
                segments_info.append(("target", i, seg))
            elif seg.is_type("comma"):
                segments_info.append(("comma", i, seg))
            elif seg.is_type("whitespace"):
                segments_info.append(("whitespace", i, seg))

        if len(segments_info) >= 2:
            # Insert newline and indentation after SELECT keyword
            select_info = next((info for info in segments_info if info[0] == "select"), None)
            if select_info:
                # Find the whitespace right after SELECT to anchor our insertion
                select_idx = select_info[1]
                whitespace_after_select = None
                if select_idx + 1 < len(segment.segments):
                    next_seg = segment.segments[select_idx + 1]
                    if next_seg.is_type("whitespace"):
                        whitespace_after_select = next_seg

                if whitespace_after_select:
                    # Insert newline and indentation after the whitespace
                    pos_marker = whitespace_after_select.pos_marker
                    newline_seg = self.make_newline(pos_marker)
                    whitespace_seg = self.make_whitespace("    ", pos_marker)
                    fixes.append(LintFix("create", whitespace_after_select, [newline_seg, whitespace_seg]))
                else:
                    # No whitespace after SELECT, insert after SELECT itself
                    pos_marker = select_info[2].pos_marker
                    newline_seg = self.make_newline(pos_marker)
                    whitespace_seg = self.make_whitespace("    ", pos_marker)
                    fixes.append(LintFix("create", select_info[2], [newline_seg, whitespace_seg]))

            # For each target (except first), insert newline and indentation before it
            # We need to find the whitespace that comes right before each target
            target_infos = [info for info in segments_info if info[0] == "target"]
            for i, target_info in enumerate(target_infos):
                if i > 0:  # Skip first target
                    target_idx = target_info[1]
                    # Look for the comma that precedes this target
                    comma_pos = -1
                    for j in range(target_idx - 1, -1, -1):
                        if segment.segments[j].is_type("comma"):
                            comma_pos = j
                            break

                    if comma_pos != -1:
                        # Find the whitespace after the comma
                        ws_pos = comma_pos + 1
                        if (ws_pos < len(segment.segments) and 
                            segment.segments[ws_pos].is_type("whitespace")):
                            # Anchor on the whitespace after comma
                            anchor_seg = segment.segments[ws_pos]
                            pos_marker = anchor_seg.pos_marker
                            newline_seg = self.make_newline(pos_marker)
                            whitespace_seg = self.make_whitespace("    ", pos_marker)
                            fixes.append(LintFix("create", anchor_seg, [newline_seg, whitespace_seg]))

        return LintResult(anchor=segment, fixes=fixes)
    else:
        # ensure newline before select target and whitespace segment
        if (
            eval_result.first_new_line_idx
            < eval_result.first_whitespace_idx
            < eval_result.first_select_target_idx
        ):
            return None
        else:
            return LintResult(anchor=segment)

