#!/usr/bin/env python3
"""
Reproduction script for the issue with Query filter with default `null` filter causing error.

This script reproduces the AttributeError: 'NullValueNode' object has no attribute 'fields'
error that occurs when using a GraphQL schema with a field that has an input object 
argument with a default value of `null`.
"""

from ariadne import make_executable_schema

# Define the GraphQL schema that causes the issue
type_defs = """
    type Query {
        """Get sensors with filtering"""
        sensors(filters: SensorFilters = null): [Sensor!]!
    }

    input SensorFilters {
        name: String
        type: String
    }

    type Sensor {
        id: ID!
        name: String!
        type: String!
    }
"""

def test_null_default_filter():
    """Test that reproduces the issue with null default filter values."""
    print("Testing schema with null default filter...")

    try:
        # This should trigger the error in Ariadne >= 0.14.0
        schema = make_executable_schema(type_defs)
        print("SUCCESS: Schema created without errors!")
        return True
    except Exception as e:
        print(f"ERROR: {type(e).__name__}: {e}")
        return False

if __name__ == "__main__":
    success = test_null_default_filter()
    if not success:
        exit(1)
    print("All tests passed!")

