class SDFDataset(xr.Dataset):
    """Custom Dataset class that handles name translation for backward compatibility"""

    __slots__ = ('_name_mapping',)

    def __init__(self, data_vars=None, coords=None, attrs=None, name_mapping=None):
        super().__init__(data_vars, coords, attrs)
        self._name_mapping = name_mapping or {}

