        # Try original key first
        if key in self.data_vars or key in self.coords:
            return super().__getitem__(key)

        # Try mapped key
        if key in self._name_mapping:
            mapped_key = self._name_mapping[key]
            if mapped_key in self.data_vars or mapped_key in self.coords:
                return super().__getitem__(mapped_key)

        # Fall back to standard behavior
        return super().__getitem__(key)

    def __contains__(self, key):
        # Check original key
        if super().__contains__(key):
            return True

        # Check mapped key
        if key in self._name_mapping:
            return super().__contains__(self._name_mapping[key])

        return False

    @property
    def coords(self):
        # Return a special coordinate accessor that also handles name mapping
        class MappedCoordinates:
            def __init__(self, original_coords, name_mapping):
                self._original_coords = original_coords
                self._name_mapping = name_mapping

            def __getitem__(self, key):
                if key in self._original_coords:
                    return self._original_coords[key]
                if key in self._name_mapping:
                    mapped_key = self._name_mapping[key]
                    if mapped_key in self._original_coords:
                        return self._original_coords[mapped_key]
                return self._original_coords[key]  # Will raise KeyError

            def __contains__(self, key):
                if key in self._original_coords:
                    return True
                if key in self._name_mapping:
                    return self._name_mapping[key] in self._original_coords
                return False

            def __iter__(self):
                return iter(self._original_coords)

            def keys(self):
                return self._original_coords.keys()

            def values(self):
                return self._original_coords.values()

            def items(self):
                return self._original_coords.items()

        return MappedCoordinates(super().coords, self._name_mapping)

