import os
import sys
from pathlib import Path
from typing import Iterable

import click
import yaml

from .formatters import (JsonFormatter, MarkdownFormatter, TerminalFormatter,
                         TsvFormatter)
from .linter import Linter
from .config.datamodel.config import RuleLevel

YAML_SUFFIXES = [".yml", ".yaml"]
DEFAULT_CONFIG_FILES = [".linkmllint.yaml", ".linkmllint.yml"]


def get_yaml_files(root: Path) -> Iterable[str]:
    if root.is_file():
        if root.suffix not in YAML_SUFFIXES:
            raise click.UsageError("SCHEMA must be a YAML file")
        yield str(root)
    else:
        for dir, _, files in os.walk(root):
            for file in files:
                if file in DEFAULT_CONFIG_FILES:
                    continue
                path = Path(dir, file)
                if path.suffix in YAML_SUFFIXES:
                    yield str(path)


@click.command()
@click.argument(
    "schema",
    type=click.Path(
        exists=True, dir_okay=True, file_okay=True, resolve_path=True, path_type=Path
    ),
)
@click.option(
    "-c", "--config", type=click.Path(exists=True, dir_okay=False, resolve_path=True)
)
@click.option(
    "-f",
    "--format",
    type=click.Choice(["terminal", "markdown", "json", "tsv"]),
    default="terminal",
)
@click.option("-o", "--output", type=click.File("w"), default="-")
@click.option("--fix/--no-fix", default=False)
@click.option("--warnings-as-errors/--no-warnings-as-errors", default=True, 
              help="Treat warnings as errors for exit code calculation (default: True for backward compatibility)")
def main(schema: Path, fix: bool, config: str, format: str, output, warnings_as_errors: bool):
    config_file = None
    if config:
        config_file = config
    else:
        for default_config in DEFAULT_CONFIG_FILES:
            path = Path(os.getcwd()) / default_config
            if path.exists():
                config_file = path
                break

    if config_file:
        with open(config_file) as f:
            config_dict = yaml.safe_load(f)
    else:
        config_dict = {"extends": "recommended"}

    linter = Linter(config_dict)
    if format == "terminal":
        formatter = TerminalFormatter(output)
    elif format == "markdown":
        formatter = MarkdownFormatter(output)
    elif format == "json":
        formatter = JsonFormatter(output)
    elif format == "tsv":
        formatter = TsvFormatter(output)

    exit_code = 0
    formatter.start_report()
    for path in get_yaml_files(schema):
        formatter.start_schema(path)
        report = linter.lint(path, fix=fix)
        warnings_count = 0
        errors_count = 0

        for problem in report:
            if problem.level and str(problem.level) == RuleLevel.warning.text:
                warnings_count += 1
            elif problem.level and str(problem.level) == RuleLevel.error.text:
                errors_count += 1
            else:
                # Treat unknown levels as errors for safety
                errors_count += 1

            formatter.handle_problem(problem)

        formatter.end_schema()

        # Calculate exit code based on warnings_as_errors flag
        if errors_count > 0:
            exit_code = max(exit_code, 10)  # Errors always cause non-zero exit
        elif warnings_count > 0 and warnings_as_errors:
            exit_code = max(exit_code, 1)   # Warnings cause exit code 1 only if flag is set

    formatter.end_report()

    sys.exit(exit_code)

