#!/usr/bin/env python3
"""Test that the fix resolves the issue."""

import json
from apispec import APISpec
from apispec.ext.marshmallow import MarshmallowPlugin


def test_fix_resolves_issue():
    """Test that the fix resolves the mixed response code issue."""

    # Create an APISpec
    spec = APISpec(
        title="Test API",
        version="1.0.0",
        openapi_version="3.0.2",
        plugins=[MarshmallowPlugin()],
    )

    # Manually create operations with mixed types to test the fix
    operations = {
        'get': {
            'description': 'Test endpoint',
            'responses': {
                200: {
                    'content': {
                        'application/json': {
                            'schema': {
                                'type': 'object',
                                'properties': {'message': {'type': 'string'}}
                            }
                        }
                    }
                },
                '4XX': {
                    'content': {
                        'application/json': {
                            'schema': {
                                'type': 'object',
                                'properties': {'error': {'type': 'string'}}
                            }
                        }
                    }
                }
            }
        }
    }

    print("=== Testing Fix for Mixed Response Codes ===")
    print("Original operation response keys:", list(operations['get']['responses'].keys()))
    print("Key types:", [type(k).__name__ for k in operations['get']['responses'].keys()])

    # Add the path manually 
    spec.path(path="/test", operations=operations)

    # Check internal structure after processing
    internal_responses = spec._paths["/test"]["get"]["responses"]
    print("Processed response keys:", list(internal_responses.keys()))
    print("Processed key types:", [type(k).__name__ for k in internal_responses.keys()])

    # Verify all keys are now strings
    all_strings = all(isinstance(k, str) for k in internal_responses.keys())
    print(f"All keys are strings: {all_strings}")

    # Try to serialize to JSON - this should now work
    print("\nAttempting JSON serialization...")
    try:
        spec_dict = spec.to_dict()
        json_output = json.dumps(spec_dict, indent=2)
        print("SUCCESS: JSON serialization worked!")
        print("Sample of serialized output:")
        lines = json_output.split('\n')
        for i, line in enumerate(lines[:20]):  # Show first 20 lines
            print(f"{i+1:2d}: {line}")
        if len(lines) > 20:
            print("   ... (output truncated)")
        return True
    except Exception as e:
        print(f"ERROR: {type(e).__name__}: {e}")
        import traceback
        traceback.print_exc()
        return False


def test_backward_compatibility():
    """Test that string-only response codes still work."""

    # Create an APISpec
    spec = APISpec(
        title="Test API",
        version="1.0.0",
        openapi_version="3.0.2",
        plugins=[MarshmallowPlugin()],
    )

    # Operations with string response codes only
    operations = {
        'get': {
            'description': 'Test endpoint',
            'responses': {
                '200': {
                    'content': {
                        'application/json': {
                            'schema': {
                                'type': 'object',
                                'properties': {'message': {'type': 'string'}}
                            }
                        }
                    }
                },
                '404': {
                    'content': {
                        'application/json': {
                            'schema': {
                                'type': 'object',
                                'properties': {'error': {'type': 'string'}}
                            }
                        }
                    }
                }
            }
        }
    }

    print("\n=== Testing Backward Compatibility ===")
    print("String-only response keys:", list(operations['get']['responses'].keys()))

    spec.path(path="/test2", operations=operations)

    internal_responses = spec._paths["/test2"]["get"]["responses"]
    print("Processed response keys:", list(internal_responses.keys()))

    all_strings = all(isinstance(k, str) for k in internal_responses.keys())
    print(f"All keys are strings: {all_strings}")

    try:
        spec_dict = spec.to_dict()
        json_output = json.dumps(spec_dict)
        print("SUCCESS: String-only responses still work!")
        return True
    except Exception as e:
        print(f"ERROR: {type(e).__name__}: {e}")
        return False


if __name__ == "__main__":
    print("Testing the fix for mixed response code types...\n")

    fix_works = test_fix_resolves_issue()
    compat_works = test_backward_compatibility()

    print(f"\n=== Results ===")
    print(f"Fix resolves issue: {fix_works}")
    print(f"Backward compatibility: {compat_works}")

    if fix_works and compat_works:
        print("\n✓ All tests passed! Fix is working correctly.")
    else:
        print("\n✗ Some tests failed. Fix needs revision.")

