#!/usr/bin/env python3
"""Simple final test demonstrating the fix works."""

import json
from apispec import APISpec
from apispec.ext.marshmallow import MarshmallowPlugin


def test_fix_works():
    """Test that the fix resolves the original issue."""

    print("=== Testing That Fix Resolves Original Issue ===")

    # Create an APISpec
    spec = APISpec(
        title="Test API", 
        version="1.0.0",
        openapi_version="3.0.2",
        plugins=[MarshmallowPlugin()],
    )

    # Create operations with the exact mixed types from the issue
    operations = {
        'get': {
            'description': 'Test endpoint',
            'responses': {
                200: {
                    'content': {
                        'application/json': {
                            'schema': {
                                'type': 'object',
                                'properties': {
                                    'message': {'type': 'string'}
                                }
                            }
                        }
                    }
                },
                '4XX': {
                    'content': {
                        'application/json': {
                            'schema': {
                                'type': 'object',
                                'properties': {
                                    'error': {'type': 'string'}
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    print("Input response keys:", list(operations['get']['responses'].keys()))
    print("Input key types:", [type(k).__name__ for k in operations['get']['responses'].keys()])

    # Add to spec - this is where the fix kicks in
    spec.path(path="/test", operations=operations)

    # Check that all response codes are now strings
    processed_responses = spec._paths["/test"]["get"]["responses"] 
    print("Output response keys:", list(processed_responses.keys()))
    print("Output key types:", [type(k).__name__ for k in processed_responses.keys()])

    # Verify all keys are strings (the fix)
    all_strings = all(isinstance(k, str) for k in processed_responses.keys())
    print(f"All response codes converted to strings: {all_strings}")

    # This was the original failing operation - JSON serialization
    print("\nTesting JSON serialization (was failing before fix)...")
    try:
        spec_dict = spec.to_dict()
        json_output = json.dumps(spec_dict)
        print("✅ SUCCESS: JSON serialization works without errors!")
        return True
    except TypeError as e:
        if "'<' not supported between instances" in str(e):
            print("❌ FAILED: Original sorting error still occurs!")
            print(f"   Error: {e}")
            return False
        else:
            print(f"❌ FAILED: Different error: {e}")
            return False
    except Exception as e:
        print(f"❌ FAILED: Unexpected error: {type(e).__name__}: {e}")
        return False


def test_backward_compatibility():
    """Ensure existing code still works."""

    print("\n=== Testing Backward Compatibility ===")

    spec = APISpec(
        title="Compat Test API",
        version="1.0.0", 
        openapi_version="3.0.2",
        plugins=[MarshmallowPlugin()],
    )

    # Test with string-only codes (existing behavior)
    operations = {
        'post': {
            'description': 'String-only codes',
            'responses': {
                '201': {'description': 'Created'},
                '400': {'description': 'Bad Request'},
                '500': {'description': 'Server Error'}
            }
        }
    }

    spec.path(path="/compat", operations=operations)

    processed_responses = spec._paths["/compat"]["post"]["responses"]
    print("String-only input keys:", ['201', '400', '500'])
    print("String-only output keys:", list(processed_responses.keys()))

    try:
        spec_dict = spec.to_dict()
        json_output = json.dumps(spec_dict)
        print("✅ SUCCESS: String-only codes still work!")
        return True
    except Exception as e:
        print(f"❌ FAILED: {type(e).__name__}: {e}")
        return False


if __name__ == "__main__":
    print("Final verification that the response codes fix works correctly\n")

    fix_works = test_fix_works()
    compat_works = test_backward_compatibility()

    print(f"\n=== FINAL RESULTS ===")
    print(f"✅ Original issue fixed: {fix_works}")
    print(f"✅ Backward compatibility maintained: {compat_works}")

    if fix_works and compat_works:
        print(f"\n🎉 SUCCESS! The fix is working perfectly.")
        print("Users can now safely mix integer and string response codes.")
    else:
        print(f"\n❌ FAILURE! More work needed.")

