def run(self, doc):
    """Update tab IDs."""

    # Get a list of id attributes
    used_ids = set()
    for el in doc.iter():
        if "id" in el.attrib:
            used_ids.add(el.attrib["id"])

    for el in doc.iter():
        if isinstance(el.tag, str) and el.tag.lower() == 'div':
            classes = el.attrib.get('class', '').split()
            if 'tabbed-set' in classes and (not self.alternate or 'tabbed-alternate' in classes):
                inputs = []
                labels = []
                if self.alternate:
                    for i in list(el):
                        if i.tag == 'input':
                            inputs.append(i)
                        if i.tag == 'div' and i.attrib.get('class', '') == 'tabbed-labels':
                            labels = [j for j in list(i) if j.tag == 'label']
                else:
                    for i in list(el):
                        if i.tag == 'input':
                            inputs.append(i)
                        if i.tag == 'label':
                            labels.append(i)

                # Handle focus logic - remove checked from first tab if another tab is marked for focus
                focused_index = None
                for idx, inpt in enumerate(inputs):
                    if inpt.attrib.get('data-focus') == 'true':
                        focused_index = idx
                        # Remove the focus marker as it's internal only
                        del inpt.attrib['data-focus']

                # If a focused tab was found, move the checked attribute to it
                if focused_index is not None:
                    # Remove checked from all inputs first
                    for inpt in inputs:
                        if 'checked' in inpt.attrib:
                            del inpt.attrib['checked']
                    # Add checked to the focused input
                    inputs[focused_index].attrib['checked'] = 'checked'

                # Generate slugged IDs
                for inpt, label in zip(inputs, labels):
                    text = toc.get_name(label)
                    innertext = toc.unescape(toc.stashedHTML2text(text, self.md))
                    slug = toc.unique(self.slugify(innertext, self.sep), used_ids)
                    inpt.attrib["id"] = slug
                    label.attrib["for"] = slug

