    known_keys : list of str
        The list of known dictionary keys to search within.

    Returns
    -------
    list of str
        List of matching keys, filtered and sorted by relevance.
    """
    # Get initial matches using standard substring matching
    matches = [
        key
        for key in known_keys
        if all(term in key.lower() for term in search_keys)
    ]

    if not matches:
        return matches

    # Apply improved filtering based on search term length
    filtered_matches = []
    for search_key in search_keys:
        if len(search_key) <= 2:
            # For very short terms, apply stricter filtering
            temp_matches = []
            for key in matches:
                key_lower = key.lower()
                # Check for word boundary matches
                pattern = r'(?:^|[^a-zA-Z])' + re.escape(search_key) + r'(?:[^a-zA-Z]|$)'
                if re.search(pattern, key_lower):
                    temp_matches.append(key)
                # Also include if it's a close prefix match for very short terms
                elif search_key == key_lower[:len(search_key)] and len(key) <= len(search_key) + 10:
                    temp_matches.append(key)
            matches = temp_matches
        elif len(search_key) <= 4:
            # For medium terms, limit the number of results
            if len(matches) > 15:
                matches.sort(key=lambda x: (abs(len(x) - len(search_key)), x))
                matches = matches[:15]
        else:
            # For longer terms, limit to reasonable number
            if len(matches) > 20:
                matches.sort(key=lambda x: (abs(len(x) - len(search_key)), x))
                matches = matches[:20]

    # Final sorting by relevance
    if matches:
        # Sort by average relevance across all search terms
        def relevance_score(key):
            total_diff = sum(abs(len(key) - len(term)) for term in search_keys)
            return (total_diff, len(key), key)
        matches.sort(key=relevance_score)

        # Limit final results
        if len(matches) > 20:
            matches = matches[:20]

    return matches

    if exact_matches:
        print(
            f"Results for '{' '.join(k for k in original_keys if k.strip())}': {exact_matches}"
        )
        if print_values:
            for match in exact_matches:
                print(f"{match} -> {self[match]}")
        return

    # If no exact matches, iterate over search keys individually
    for original_key, search_key in zip(original_keys, search_keys):
        exact_key_matches, partial_matches = self._find_matches(
            search_key, known_keys
        )

        if exact_key_matches:
            print(f"Exact matches for '{original_key}': {exact_key_matches}")
            if print_values:
                for match in exact_key_matches:
                    print(f"{match} -> {self[match]}")
        else:
            if partial_matches:
                print(
                    f"No exact matches found for '{original_key}'. Best matches are: {partial_matches}"
                )
            else:
                print(f"No matches found for '{original_key}'")

